const matches = $input.all();
const trigger = $('Триггер Telegram').first().json;
const chatId = String(trigger.message.chat.id);
const text = trigger.message.text || '';
const chat = trigger.message.chat;
const name = chat.first_name || chat.username || ('Клиент ' + chatId);
const row = matches.map(item => item.json).find(item => item && item.customer_chat_id != null);
if (row) {
  return [{ json: {
    found: true,
    customerChatId: chatId,
    customerName: row.customer_name,
    topicId: row.topic_id,
    mode: row.mode,
    history: row.history,
    incomingText: text
  } }];
}
return [{ json: {
  found: false,
  customerChatId: chatId,
  customerName: name,
  topicId: null,
  mode: 'ai',
  history: '[]',
  incomingText: text
} }];

const j = $input.first().json;
const base = $('Нормализация поиска треда').first().json;
const customerChatId = j.customer_chat_id ?? j.customerChatId ?? base.customerChatId;
const topicId = j.topic_id ?? j.topicId ?? base.topicId;
const mode = j.mode ?? base.mode;
const history = j.history ?? base.history;
const customerName = j.customer_name ?? j.customerName ?? base.customerName;
return [{ json: { customerChatId, customerName, topicId, mode, history, incomingText: base.incomingText } }];

const input = $input.first().json;
const csv = typeof input.priceCsv === 'string' ? input.priceCsv : '';

function parseCsv(text) {
  const rows = [];
  let row = [];
  let field = '';
  let quoted = false;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (quoted) {
      if (ch === '"' && text[i + 1] === '"') { field += '"'; i++; }
      else if (ch === '"') quoted = false;
      else field += ch;
    } else if (ch === '"') quoted = true;
    else if (ch === ',') { row.push(field); field = ''; }
    else if (ch === '\n') { row.push(field); rows.push(row); row = []; field = ''; }
    else if (ch !== '\r') field += ch;
  }
  if (field.length || row.length) { row.push(field); rows.push(row); }
  return rows;
}

const parsedRows = csv ? parseCsv(csv) : [];
const headers = (parsedRows.shift() || []).map((value, index) => String(value).trim().replace(index === 0 ? /^\uFEFF/ : /$^/, ''));
const records = parsedRows
  .filter(cells => cells.some(value => String(value).trim() !== ''))
  .map(cells => Object.fromEntries(headers.map((header, index) => [header, String(cells[index] ?? '').trim()])));
const priceRows = records
  .filter(row => row.id && row.make && row.model)
  .map(row => ({
    id: String(row.id),
    make: row.make,
    model: row.model,
    year_from: Number(row.year_from),
    year_to: Number(row.year_to),
    glass_type: row.glass_type,
    features: row.features,
    brand: row.brand,
    price_glass: Number(row.price_glass),
    price_work: Number(row.price_work),
    in_stock: row.in_stock
  }));
const thread = $('Состояние треда').first().json;
return [{ json: {
  ...thread,
  priceListAvailable: priceRows.length > 0,
  priceRows,
  priceListJson: JSON.stringify(priceRows)
} }];

const input = $input.first().json;
const raw = String(input.text || '').trim();
const context = $('Подготовить контекст прайса').first().json;
const thread = $('Состояние треда').first().json;
const priceRows = Array.isArray(context.priceRows) ? context.priceRows : [];
let parsed;
try {
  const match = raw.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(match ? match[0] : raw);
} catch (e) {
  parsed = null;
}

let reply = parsed?.reply ? String(parsed.reply).trim() : '';
let escalate = parsed?.escalate || null;
let lookupStatus = parsed?.lookupStatus || 'not_requested';
let requestedIds = Array.isArray(parsed?.matchedPriceIds) ? parsed.matchedPriceIds : [];
if (!requestedIds.length && parsed?.matchedPriceId != null) requestedIds = [parsed.matchedPriceId];
requestedIds = [...new Set(requestedIds.map(String))];
let matchedRows = [];

const money = value => Number(value).toLocaleString('ru-RU') + ' ₽';
const typeName = value => ({ Front: 'лобовое', Rear: 'заднее', Side: 'боковое' }[value] || value);
const featureNames = value => {
  const names = { 'None': 'без доп. опций', 'Rain sensor': 'датчик дождя', 'Heating': 'обогрев', 'Camera': 'камера', 'HUD': 'HUD', 'Solar': 'солнцезащитное' };
  return String(value || 'None').split(',').map(item => names[item.trim()] || item.trim()).join(', ');
};

if (!parsed) {
  reply = 'Извините, сейчас не удалось обработать запрос. Подключаю менеджера — он поможет с подбором и ценой.';
  escalate = { reason: 'ai_unavailable', summary: 'Gemini не вернул корректный JSON. Требуется ответ менеджера.' };
} else if (!context.priceListAvailable && lookupStatus !== 'not_requested') {
  lookupStatus = 'not_found';
  reply = 'Извините, сейчас не удалось получить актуальный прайс. Подключаю менеджера — он уточнит цену.';
  escalate = { reason: 'price_source_unavailable', summary: 'Не удалось загрузить прайс Google Sheets.' };
} else if (lookupStatus === 'found' || lookupStatus === 'found_multiple') {
  matchedRows = requestedIds.map(id => priceRows.find(row => String(row.id) === id)).filter(Boolean);
  if (!matchedRows.length) {
    lookupStatus = 'not_found';
    reply = 'Извините, я не нашёл подходящую цену в прайс-листе. Подключаю менеджера — он уточнит стоимость.';
    escalate = { reason: 'price_not_found', summary: 'Модель не указала существующие id строк прайса для запроса: ' + thread.incomingText };
  } else if (matchedRows.length > 5) {
    lookupStatus = 'need_details';
    matchedRows = [];
    reply = 'Нашлось много вариантов. Уточните, пожалуйста, комплектацию стекла: наличие датчика дождя, обогрева, камеры или HUD.';
    escalate = null;
  } else {
    if (escalate && ['price_not_found', 'price_source_unavailable'].includes(escalate.reason)) escalate = null;
    const lines = matchedRows.map((row, index) => {
      const total = Number(row.price_glass) + Number(row.price_work);
      const availability = String(row.in_stock).toLowerCase() === 'yes' ? 'в наличии' : 'нет в наличии';
      return (matchedRows.length > 1 ? (index + 1) + '. ' : '') + row.brand + ', ' + featureNames(row.features) + ', ' + row.year_from + '–' + row.year_to + ': стекло ' + money(row.price_glass) + ' + установка ' + money(row.price_work) + ' = ' + money(total) + '; ' + availability + '.';
    });
    const first = matchedRows[0];
    const heading = matchedRows.length > 1
      ? 'Для ' + first.make + ' ' + first.model + ', ' + typeName(first.glass_type) + ' стекло, нашёл ' + matchedRows.length + ' варианта:'
      : 'По прайсу для ' + first.make + ' ' + first.model + ', ' + typeName(first.glass_type) + ' стекло:';
    reply = heading + '\n' + lines.join('\n');
    const availableCount = matchedRows.filter(row => String(row.in_stock).toLowerCase() === 'yes').length;
    if (availableCount === 0 && !escalate) {
      escalate = { reason: 'not_in_stock', summary: 'Все найденные позиции (' + requestedIds.join(', ') + ') отсутствуют в наличии; нужны альтернативы.' };
      reply += '\nСейчас эти позиции отмечены как отсутствующие. Подключаю менеджера, чтобы проверить альтернативы.';
    }
  }
} else if (lookupStatus === 'not_found') {
  reply = 'Извините, я не нашёл подходящую цену в прайс-листе. Подключаю менеджера — он уточнит стоимость.';
  escalate = escalate || { reason: 'price_not_found', summary: 'Цена не найдена для запроса: ' + thread.incomingText };
} else if (lookupStatus === 'need_details' && !reply) {
  reply = 'Уточните, пожалуйста, марку, модель, год автомобиля и какое стекло требуется: лобовое, заднее или боковое?';
}

if (!reply) reply = 'Чем могу помочь с подбором автостекла?';
let history = [];
try { history = JSON.parse(thread.history || '[]'); } catch (e) { history = []; }
history.push({ role: 'customer', text: thread.incomingText });
history.push({ role: 'assistant', text: reply });
if (history.length > 20) history = history.slice(-20);
const newMode = escalate ? 'human' : (thread.mode || 'ai');
return [{ json: {
  customerChatId: thread.customerChatId,
  topicId: thread.topicId,
  reply,
  escalate,
  newMode,
  updatedHistory: JSON.stringify(history),
  lookupStatus,
  matchedPriceId: matchedRows.length === 1 ? matchedRows[0].id : null,
  matchedPriceIds: matchedRows.map(row => row.id)
} }];

const matches = $input.all();
const trigger = $('Триггер Telegram').first().json;
const text = trigger.message.text || '';
const row = matches.map(item => item.json).find(item => item && item.topic_id != null);
if (row) {
  return [{ json: { found: true, customerChatId: row.customer_chat_id, topicId: row.topic_id, text } }];
}
return [{ json: { found: false, customerChatId: null, topicId: trigger.message.message_thread_id, text } }];

const state = $input.first().json;
const currentMode = state.mode || 'ai';
const newMode = currentMode === 'ai' ? 'human' : 'ai';
let history = [];
try { history = JSON.parse(state.history || '[]'); } catch (e) { history = []; }
history.push({ role: 'system', text: 'Режим изменен пользователем на ' + newMode });
return [{ json: {
  customerChatId: state.customerChatId,
  topicId: state.topicId,
  newMode: newMode,
  updatedHistory: JSON.stringify(history)
} }];
